if($_SERVER['REQUEST_METHOD']==='POST'){ csrf_check(); if(!rate_limit('inquiry',4)) $error='Please wait before submitting another inquiry.'; elseif(empty($_POST['bride_name'])||!filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL)) $error='Please provide your name and a valid email address.'; else { try { $file=null; if(!empty($_FILES['inspiration']['name'])){ $ok=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['inspiration']['tmp_name']); if(!isset($ok[$mime])||$_FILES['inspiration']['size']>5*1024*1024) throw new RuntimeException('Upload a JPG, PNG, or WebP image under 5 MB.'); $name=bin2hex(random_bytes(16)).'.'.$ok[$mime]; if(!is_dir(ROOT_PATH.'/storage/uploads')) mkdir(ROOT_PATH.'/storage/uploads',0755,true); move_uploaded_file($_FILES['inspiration']['tmp_name'],ROOT_PATH.'/storage/uploads/'.$name); $file='storage/uploads/'.$name; } $q=db()->prepare('INSERT INTO inquiries (bride_name,groom_name,email,phone,wedding_date,venue,guests,decoration_style,flower_preference,budget,contact_method,notes,inspiration_path) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)'); $q->execute([trim($_POST['bride_name']),trim($_POST['groom_name']),trim($_POST['email']),trim($_POST['phone']),$_POST['wedding_date']?:null,trim($_POST['venue']),$_POST['guests']?:null,trim($_POST['style']),trim($_POST['flowers']),trim($_POST['budget']),$_POST['contact_method'],trim($_POST['notes']),$file]); $sent=true; } catch(Throwable $e){ $error='We could not save your inquiry. Please contact us via WhatsApp.'; }}}
