<main id="main"><section class="page-hero"><p class="eyebrow">Begin your floral story</p><h1>Tell us about the day you’re dreaming of.</h1><p>Share the details below and our team will be in touch during customer service hours (09:00–20:00).</p></section><section class="section tinted"><div class="form-wrap"><?php if($sent):?><div class="alert"><strong>Thank you — your inquiry is with us.</strong> We’ll be in touch soon with the next steps.</div><?php else: if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="form-grid"><p class="full"><strong>Your celebration</strong></p><p><label for="bride_name">Bride’s name *</label><input required id="bride_name" name="bride_name" autocomplete="name"></p><p><label for="groom_name">Groom’s name</label><input id="groom_name" name="groom_name"></p><p><label for="email">Email *</label><input required type="email" id="email" name="email" autocomplete="email"></p><p><label for="phone">Phone number *</label><input required id="phone" name="phone" inputmode="tel" autocomplete="tel"></p><p><label for="wedding_date">Wedding date</label><input type="date" id="wedding_date" name="wedding_date"></p><p><label for="venue">Wedding venue</label><input id="venue" name="venue"></p><p><label for="guests">Estimated guests</label><input type="number" min="1" id="guests" name="guests"></p><p><label for="style">Decoration style</label><select id="style" name="style"><option value="">Select a style</option><option>Classic romance</option><option>Modern minimal</option><option>Garden-inspired</option><option>Editorial luxury</option><option>Not sure yet</option></select></p><p><label for="flowers">Flower preferences</label><input id="flowers" name="flowers" placeholder="e.g. roses, orchids, peonies"></p><p><label for="budget">Estimated budget</label><input id="budget" name="budget" placeholder="Your comfortable range"></p><p><label for="contact_method">Preferred contact method</label><select id="contact_method" name="contact_method"><option>WhatsApp</option><option>Email</option><option>Phone call</option></select></p><p><label for="inspiration">Inspiration photos (optional)</label><input type="file" accept="image/jpeg,image/png,image/webp" id="inspiration" name="inspiration"><small class="help">JPG, PNG or WebP · 5 MB maximum</small></p><p class="full"><label for="notes">Anything else we should know?</label><textarea id="notes" name="notes" placeholder="Tell us about the feeling you want to create."></textarea></p><p class="full"><button class="button gold" type="submit">Send my inquiry</button></p></div></form><?php endif;?></div></section></main><?php page_footer(); ?>
